package com.littlemakers.village.nativeapp;
public final class VisualGeometry38Test {
 static int checks;static void check(boolean b,String m){checks++;if(!b)throw new AssertionError(m);}
 public static void main(String[]args){float[]v=FishGeometry.build();check(v.length%21==0&&v.length/7<6000,"triangle format and mobile budget");boolean tail=false,fin=false,eye=false;for(int i=0;i<v.length;i+=7){for(int c=0;c<7;c++)check(Float.isFinite(v[i+c]),"finite vertex");float len=v[i+3]*v[i+3]+v[i+4]*v[i+4]+v[i+5]*v[i+5];check(Math.abs(len-1)<.0001,"unit normal");tail|=v[i]<-.9;fin|=v[i+6]==1;eye|=v[i+6]>=2;}check(tail&&fin&&eye,"fish anatomy");check(FishGeometry.bend(.5f,0)==0&&Math.abs(FishGeometry.bend(-1,0)-FishGeometry.bend(-1,.3f))>.05,"stable head and swimming tail");int rows=17,cols=32;float[][]p=new float[rows*cols][3],n=new float[p.length][3];for(int r=0;r<rows;r++)for(int c=0;c<cols;c++){double lat=Math.PI*r/(rows-1),lon=Math.PI*2*c/cols;p[r*cols+c]=new float[]{(float)(Math.sin(lat)*Math.cos(lon)),(float)Math.cos(lat),(float)(Math.sin(lat)*Math.sin(lon))};}SurfaceNormals.calculate(p,rows,cols,n);for(int i=0;i<p.length;i++)check(p[i][0]*n[i][0]+p[i][1]*n[i][1]+p[i][2]*n[i][2]>.98,"outward smooth normals");float before=n[4*cols][0];for(float[]a:p)a[0]*=1.6;SurfaceNormals.calculate(p,rows,cols,n);check(Math.abs(n[4*cols][0]-before)>.1,"sculpted geometry changes normal");for(float[]a:p)java.util.Arrays.fill(a,0);SurfaceNormals.calculate(p,rows,cols,n);for(float[]a:n)for(float f:a)check(Float.isFinite(f),"collapsed geometry safe");System.out.println("PASS "+checks+" fish geometry/swimming and sculpted-normal assertions; not a game count or physical FPS benchmark.");}
}
